CREATE DEFINER=`root`@`localhost` EVENT `update_categories_weekly` ON SCHEDULE EVERY 1 WEEK STARTS '2025-06-24 13:27:51' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Đặt tất cả về 'disabled'
    UPDATE categories SET status = 'disabled';

    -- Đặt ngẫu nhiên 3 cái thành 'active'
    UPDATE categories
    SET status = 'active'
    WHERE id IN (
        SELECT id FROM (
            SELECT id FROM categories ORDER BY RAND() LIMIT 3
        ) AS tmp
    );
END$$

